<template><AccountLayout bare><div class="container py-4"><section class="card border-0 shadow-sm mb-4"><div class="card-body d-flex justify-content-between align-items-center"><div><small class="text-uppercase text-muted fw-bold">Profiles Module</small><h2 class="mb-1">Account Groups</h2><span class="text-muted">Dashboard &gt; Profiles &gt; Account Groups</span></div><button class="btn btn-primary" @click="newGroup">+ New Account Group</button></div></section><div v-if="error" class="alert alert-danger">{{error}}</div><section class="card shadow-sm border-0 mb-4"><div class="card-body"><input v-model="search" class="form-control" placeholder="Search account groups" /></div></section><form v-if="editing" class="card shadow-sm border-0 mb-4" @submit.prevent="save"><div class="card-body row g-3"><h5 class="text-primary">{{form.id?'Edit':'New'}} Account Group</h5><div v-for="[key,label,option] in fields" :key="key" class="col-md-4"><label class="form-label">{{label}}</label><select v-if="option" v-model="form[key]" class="form-select" required><option v-for="(name,id) in options[option]" :key="id" :value="Number(id)">{{name}}</option></select><input v-else v-model="form[key]" class="form-control" required /></div><div class="col-md-4"><label class="form-label">Status</label><select v-model="form.status_active" class="form-select"><option :value="true">Active</option><option :value="false">Inactive</option></select></div><div class="col-12"><button class="btn btn-primary me-2">Save</button><button type="button" class="btn btn-outline-secondary" @click="editing=false">Cancel</button></div></div></form><section class="card shadow-sm border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Code</th><th>Account Group</th><th>Main Group</th><th>Statement Type</th><th>Account Type</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="g in filtered" :key="g.id"><td>{{g.sub_group_code}}</td><td>{{g.sub_group}}</td><td>{{name('main_groups',g.main_group)}}</td><td>{{name('statement_types',g.statement_type)}}</td><td>{{name('account_types',g.account_type)}}</td><td><span class="badge" :class="g.status_active?'text-bg-success':'text-bg-secondary'">{{g.status_active?'Active':'Inactive'}}</span></td><td><button class="btn btn-sm btn-outline-primary me-2" @click="edit(g)">Edit</button><button class="btn btn-sm btn-outline-danger" @click="remove(g)">Delete</button></td></tr></tbody></table></div></section></div></AccountLayout></template>
<script setup>import{computed,onMounted,ref}from'vue';import client from'../api/client';import AccountLayout from'../components/AccountLayout.vue';const groups=ref([]),options=ref({}),search=ref(''),editing=ref(false),error=ref(''),form=ref({}),fields=[['sub_group','Account Group'],['main_group','Main Group','main_groups'],['statement_type','Statement Type','statement_types'],['account_type','Account Type','account_types'],['cash_flow_group','Cash Flow Group','cash_flow_groups']];const filtered=computed(()=>groups.value.filter(g=>`${g.sub_group_code} ${g.sub_group}`.toLowerCase().includes(search.value.toLowerCase())));const name=(k,v)=>options.value[k]?.[v]||'—';const load=async()=>{let[a,b]=await Promise.all([client.get('/account-groups'),client.get('/account-groups/options')]);groups.value=a.data.data;options.value=b.data.data};const newGroup=()=>{form.value={main_group:1,sub_group:'',statement_type:1,account_type:1,cash_flow_group:1,status_active:true};editing.value=true};const edit=g=>{form.value={...g};editing.value=true};const save=async()=>{try{await(form.value.id?client.put(`/account-groups/${form.value.id}`,form.value):client.post('/account-groups',form.value));editing.value=false;await load()}catch(e){error.value=e.response?.data?.message||'Unable to save account group.'}};const remove=async g=>{if(confirm(`Delete ${g.sub_group}?`)){await client.delete(`/account-groups/${g.id}`);await load()}};onMounted(()=>load().catch(()=>error.value='Unable to load account groups.'))</script>
